        descripcion: 'La Coordinación Estatal de Protección Civil de Morelos (CEPCM), dirigida por Ubaldo González Carretes, es el organismo rector del sistema estatal de emergencias pero no cuenta con brigada de bomberos propia: la responsabilidad constitucional recae en los 36 municipios (Art. 114 BIS de la Constitución de Morelos). La CEPCM opera la Dirección de Atención a Emergencias y Desastres con 20 elementos especializados, centro de mando móvil, ATVs para zonas de difícil acceso y drones de reconocimiento.\n\nEn junio de 2026, el coordinador González Carretes anunció un plan para dividir Morelos en 5 regiones operativas de bomberos y protección civil, reconociendo explícitamente las carencias en personal especializado, equipo técnico y vehículos que afectan a varios municipios. Morelos no cuenta con Ley de Bomberos propia; la normativa se fragmenta entre el Art. 19 de la Ley de Protección Civil 2014 y reglamentos municipales heterogéneos.\n\nEl corredor Popocatépetl —con seis municipios morelenses a menos de 20 km del cráter (Tetela del Volcán, Hueyapan, Ocuituco, Temoac, Yecapixtla, Zacualpan de Amilpas)— es la principal prioridad volcánica: en 2025 la CEPCM y CENAPRED coordinaron rutas de evacuación con inversión histórica de $147 millones de pesos. Aproximadamente 20–25 de los 36 municipios del estado carecen de cuerpo de bomberos propio y dependen de la CEPCM como respaldo operativo.',
