        descripcion: 'La Dirección de Bomberos, Rescate y Urgencias Médicas de Cuernavaca, encabezada por el director Moisés Ramos González, es la corporación más antigua y mejor equipada del estado. Opera desde cuatro bases (Estación Central en Blvd. del Lago, Base Zapata en Av. Emiliano Zapata, y dos subestaciones adicionales), con aproximadamente 90 bomberos activos y 20 voluntarios adscritos.\n\nEn 2025 la corporación atendió más de 2,000 servicios: 596 enjambres de abejas, 395 árboles caídos, 243 incendios en terrenos baldíos, 234 fugas de gas, 62 incendios en casa habitación, 56 inundaciones, 43 incendios de vehículo y 36 personas rescatadas. En septiembre de 2025 el ayuntamiento realizó una inversión de $6,169,628.19 pesos para una pipa cisterna modelo 2025 de 4,000 litros con bomba portátil; previamente en abril de 2023 recibieron dos camiones de bomberos y una ambulancia donados por la ciudad de Minneapolis.\n\nLa estación central (777 322-8753) y la Base Zapata (777 374-5099) son los puntos de contacto operativo. La adscripción administrativa es el Centro de Mando C4 (777 312-1274). La corporación cubre Cuernavaca y actúa como respaldo para municipios del corredor metropolitano que carecen de cuerpo propio.',
