        descripcion: 'Bomberos de Nuevo León, A.B.P. (Asociación de Beneficencia Privada) es el modelo más singular del país: una corporación privada de beneficencia, sin dependencia gubernamental directa, que presta el servicio de bomberos a 6 municipios del área metropolitana de Monterrey (Monterrey, Apodaca, Escobedo, San Pedro Garza García, Santa Catarina y Salinas Victoria). Fundada en 1908 por iniciativa empresarial —con la primera estación en la calle Juárez— fue constituida formalmente como A.C. en 1954 y transformada en A.B.P. en 2011. El financiamiento proviene de convenios con los municipios, empresas donatarias (TERNIUM, FEMSA, ARCA, CEMEX, ALFA) y sorteos anuales. Desde el 28 de mayo de 2025, la dirección está a cargo de Guillermo Dillon Montaña (ex director de CAINTRA NL por casi dos décadas); el Patronato está presidido desde abril 2026 por Andrés Elosúa González.\n\nEn 2025 atendió 7,913 emergencias (+20% vs. 2024), con un pico de más de 80 siniestros en un solo día (4 de marzo de 2025) y más de 850 incendios en solo el mes de marzo. Opera 15 estaciones activas con 150 elementos profesionales y 30 voluntarios, cubriendo una población de más de 3.2 millones de personas. La Academia de Formación de Bomberos (en la Estación Central) gradúa nuevas generaciones cada 10 meses. El déficit estructural es reconocido por la propia institución: debería operar 30 estaciones para el área que cubre actualmente.',
