        descripcion: 'La Dirección de Protección Civil y Bomberos de Santiago, N.L. —bajo el mando del Cmte. Saúl Mata Alanís y el Coordinador Operativo Lic. Mario Ernesto Rodríguez Cobas— es la corporación con mayor especialización en rescate de montaña y combate de incendios forestales del estado. Santiago incluye el Parque Nacional Cumbres de Monterrey (zona protegida federal) y destinos como Cola de Caballo, Cañón de Matacanes y La Estanzuela, lo que genera una demanda permanente de rescate técnico en alturas y barrancas.\n\nLa corporación cuenta con 2 camiones de bombero, 3 unidades de ataque rápido, 2 unidades todo terreno, 1 helicóptero, 4 motocicletas, 4 ambulancias y 2 pipas, más 24 paramédicos/rescatistas y 10 voluntarios, según el Plan de Incendios Forestales y Estiaje 2025 publicado en mirror.santiago.gob.mx. Santiago ha sido históricamente el municipio con mayor afectación forestal de NL (14,000 ha en 2021; 3,200 ha en 2023). En 2025 el personal recibió cámaras corporales con IA en preparación para el Mundial FIFA 2026.',
