        descripcion: 'El Cuerpo de Rescate y Extinción de Incendios (CREI) del Aeropuerto Internacional General Mariano Escobedo (MTY/MMMY) —segundo aeropuerto de mayor tráfico de México con 15.6 millones de pasajeros en 2025— es operado por OMA (Grupo Aeroportuario del Centro Norte). El aeropuerto está certificado por la AFAC (Agencia Federal de Aviación Civil) y el CREI opera con Categoría 7 OACI (fuente: directorio aeronáutico AC-U-KWIK), habilitado para atender aeronaves de la categoría de jets comerciales medianos y grandes.\n\nOMA opera el aeropuerto desde su concesión original; el recinto está ubicado en Apodaca, NL, en el corazón del corredor industrial más activo de México. Dada la expansión del tráfico aéreo, la categoría SSEI podría haberse actualizado a Cat. 8 o Cat. 9 en documentación interna operacional —la fuente AFAC más reciente verificable es Cat. 7. El aeropuerto recibe vuelos internacionales de amplio cuerpo (B787, A330).',
