        descripcion: 'Fundado el 2 de diciembre de 1954 tras un incendio devastador en el centro histórico de Oaxaca de Juárez, el Heroico Cuerpo de Bomberos de Oaxaca (HCBO) es la institución de bomberos más antigua e importante del estado, adscrita a la Secretaría de Seguridad y Protección Ciudadana (SSPC/SSPO). A diferencia del modelo municipal predominante en México, el HCBO opera como corporación ESTATAL centralizada —similar al modelo de Nayarit— con cobertura nominal sobre los 570 municipios del estado con mayor diversidad municipal del país, a través de una red de subestaciones regionales inauguradas progresivamente desde 2016.\n\nCon 255 elementos operativos en 2025 (dato octubre, El Imparcial de Oaxaca) y al menos 10 subestaciones verificadas al cierre de 2024, el HCBO atiende incendios estructurales, rescates vehiculares y acuáticos, emergencias médicas y eventos de gran convocatoria como la Guelaguetza. Su flota incluía 59 vehículos en 2016 (autobombas, tanques, ambulancias, unidades de ataque rápido, motos y acuáticos), número actualizado con nuevas adquisiciones. En octubre 2025, el director Jorge Arturo Rivas Fernández del Río (en funciones desde agosto 2024) declaró que Oaxaca requiere al menos 1,000 bomberos para cobertura adecuada de su extenso y complejo territorio serrano, costero e indígena.',
