        descripcion: 'La Coordinación de Protección Civil y Bomberos Municipales de Salina Cruz opera como unidad integrada bajo la administración municipal, cubriendo el puerto de Salina Cruz —uno de los puertos comerciales más activos del Pacífico mexicano y sede de la única refinería de PEMEX en el sur del país. La coordinadora del período 2025-2027 es Mireya Soto Silva (dato verificado en salina-cruz.gob.mx, enero 2025). El cuerpo opera como primera respuesta externa en incidentes mayores en la Refinería "Ing. Antonio Dovalí Jaime", complementando la brigada interna de PEMEX cuando la emergencia rebasa el perímetro industrial. Su número está registrado como referencia de emergencia en el directorio oficial de ASIPONA (Administración del Sistema Portuario Nacional Salina Cruz). En diciembre de 2025 respondió conjuntamente con los bomberos de Juchitán y la brigada PEMEX a un incendio en Santo Domingo Tehuantepec.',
