        descripcion: 'La Refinería "Ing. Antonio Dovalí Jaime" de PEMEX en Salina Cruz, con capacidad instalada de 360,000 barriles diarios —la única refinería federal en el sur de México—, opera una brigada de emergencias interna en cumplimiento de la NRF-104-PEMEX y la NOM-002-STPS-2010. La existencia del "cuerpo contra incendio de la instalación" fue confirmada en comunicados oficiales de PEMEX al gestionar múltiples incidentes durante 2024-2026.\n\nEntre los incidentes documentados destacan: un incendio en septiembre 2024, otro en noviembre 2024, una explosión en la planta Hidros II el 11 de mayo de 2026 (Planta de Hidrotratamiento, torre de enfriamiento TE-05, con seis lesionados y un fallecido el 13 de mayo), y un nuevo incendio en la misma torre dañada el 1 de junio de 2026. En el incendio de Tehuantepec de diciembre 2025, los bomberos PEMEX de Salina Cruz respondieron en apoyo externo junto con los cuerpos municipales. Los detalles operativos (número de elementos y flota exacta) no son públicos en fuentes abiertas.',
