        descripcion: 'La Coordinación Municipal de Protección Civil y Bomberos de Santa María Huatulco atiende el principal destino turístico de sol y playa del Pacífico oaxaqueño, con nueve bahías y más de 800,000 visitantes anuales. Su cuartel se ubica en La Crucecita, centro urbano de las Bahías de Huatulco. En abril de 2026, el presidente municipal Ing. Julio Cárdenas encabezó una entrega oficial de equipamiento y uniformes al cuerpo, confirmando su operatividad activa bajo la administración 2022-2024 ampliada (dato verificado en huatulco.gob.mx). El cuerpo cuenta con capacidad de rescate acuático para emergencias en bahías de acceso controlado y en la costa abierta, además de atención bilingüe para turistas internacionales. Opera en coordinación con el CREI del Aeropuerto Internacional de Bahías de Huatulco (HUX), que cubre las emergencias de aviación.',
