        descripcion: 'Fundado el 2 de febrero de 1905 por el instructor Albino G. Serrano —a propuesta del Ayuntamiento encabezado por el Dr. Ernesto Espinosa Bravo y bajo el gobierno del Gral. Mucio P. Martínez—, el Heroico Cuerpo de Bomberos y Bomberas del Estado de Puebla es uno de los cuerpos de bomberos más antiguos de México. Inició con 6 elementos en un anexo del rastro municipal de la calle Viejo Río de San Jerónimo. La Estación Central lleva hoy el nombre oficial "Cmte. Albino G. Serrano" en honor a su fundador.\n\nA diferencia de la mayoría de los estados, el HCBP opera como corporación ESTATAL adscrita a la Secretaría de Seguridad Pública (SSP) —no al Ayuntamiento—, y sus integrantes tienen rango de "Policía Estatal Bombero". En noviembre de 2024, el gobernador Sergio Salomón Céspedes entregó 9 vehículos nuevos e inauguró la Estación San Ramón con inversión de 42 millones de pesos. El cuerpo registró 4,923 servicios en 2025 (834 incendios, 501 rescates). Una iniciativa legislativa de junio 2026 busca convertir al HCBP en organismo desconcentrado autónomo de la SSP, separándolo de la estructura policial. Convocatoria 2025: salario de 16,000 MXN/mes más ISSSTEP y seguro de vida.',
