        certificaciones: ['NFPA 1006 (Rescate Técnico)', 'IPR — International Paramedic Registry'],
        descripcion: 'El Heroico Cuerpo de Bomberos Voluntarios de Querétaro es la corporación de respuesta a emergencias más importante del estado, fundada el 30 de noviembre de 1949 —cuando inició operaciones— tras la firma del acta constitutiva de la Sociedad Civil "Previsión y Protección, S.C." el 30 de agosto del mismo año. El detonador fue la visita del presidente Miguel Alemán Valdéz en 1947, durante la cual un incendio expuso públicamente que la ciudad carecía de bomberos. A diferencia de la mayoría de los cuerpos en México, no es una dependencia municipal ni estatal, sino una sociedad civil de naturaleza mixta: recibe subsidio del Gobierno del Estado (canalizado vía la Coordinación Estatal de Protección Civil de Querétaro) y apoyo del Ayuntamiento capitalino, además de aportaciones de la iniciativa privada. En 2023 el gobierno estatal destinó 31.3 millones de pesos a la institución.\n\nOpera 6 estaciones estratégicamente distribuidas: Estación Central (Centro Histórico, 1963), Ampliación Jurica (1988), Vista Alegre (1994), Col. Ecológica (2005), Carretera Mompani (2016) y Santa Rosa Jáuregui (dic. 2020). En 2025 proyecta una Estación 7 en la zona norponiente. El cuerpo cuenta con Academia de Aspirantes con certificación NFPA 1006 y estatus de Centro de Entrenamiento IPR; desde 2025 entrega reconocimiento CEMEFI por 11 años consecutivos de institucionalidad y transparencia. El Consejo de Administración 2025-2027 es presidido por Sergio Arturo Pesquera Perrusquía (tomó protesta jun. 2025). Hermanamiento activo con el Cuerpo de Bomberos de Bakersfield, California (20 años).',
