        descripcion: 'El Servicio de Salvamento y Extinción de Incendios (SSEI) del Aeropuerto Intercontinental de Querétaro "Ing. Fernando Espinosa Gutiérrez" (QRO/MMQT) opera en el único aeropuerto de economía mixta entre los de mayor tráfico en México: 75% propiedad del Gobierno del Estado de Querétaro y 25% de ASA (Aeropuertos y Servicios Auxiliares). El aeropuerto fue el primero en México en obtener el Certificado de Aeródromo de la AFAC (Agencia Federal de Aviación Civil), en 2009, renovado en 2013, 2016 y 2023. La pista principal 09/27 mide 3,500 metros, habilitada para aeronaves wide-body. En 2024 el aeropuerto superó por primera vez los 2 millones de pasajeros (2,074,950), consolidándose entre los 10 terminales de mayor crecimiento del país.\n\nEl SSEI está diseñado para aeronaves de gran tonelaje bajo estándares OACI Anexo 14 y opera con tiempo de respuesta máximo de 3 minutos a cualquier punto de la pista. La terminal atiende operaciones nacionales e internacionales (EUA, Europa) de aerolíneas como Volaris, Viva Aerobus, Aeromexico, Delta Air Lines y TAR Aerolíneas, además de ser el quinto aeropuerto nacional por volumen de carga. El aeropuerto se ubica entre los municipios de El Marqués y Colón, en el corazón del corredor aeroespacial de Querétaro, el más importante de México.',
