        descripcion: 'El Heroico Cuerpo de Bomberos, Rescate, Emergencias Médicas y Desastres de Cancún es la corporación de emergencias más grande de la Península de Yucatán y una de las más activas del país. Fundado el 15 de abril de 1976 con doce elementos, una cisterna, un carro-bomba y una ambulancia, hoy opera con 176 efectivos distribuidos en seis bases que cubren la zona continental, el corredor hotelero del Caribe y la delegación Alfredo V. Bonfil. Depende del H. Ayuntamiento de Benito Juárez y cuenta con capacidades especializadas: rescate en altura con colchón de 8×10 metros hasta el piso doce, atención de incidentes con materiales peligrosos como amoniaco y gas cloro, rescate acuático en la Laguna Nichupté, y respuesta a vehículos eléctricos con baterías de litio.\n\nEn 2025 atendió 1,143 emergencias por incendio. La corporación inició en 2025 la remodelación de sus bases y proyecta una séptima estación en la zona sur. En mayo de 2026 diez bomberos resultaron intoxicados al combatir un incendio en una plaza comercial con evacuación de 300 personas. Durante el huracán Beryl de julio de 2024 la presidenta municipal reconoció expresamente su actuación en las fases preventiva, de respuesta y de recuperación.',
