        descripcion: 'El Heroico Cuerpo de Bomberos de Cozumel opera en un escenario geográfico único: la isla más grande del Caribe mexicano y uno de los destinos de buceo más importantes del mundo, donde el riesgo de incendio coexiste con emergencias náuticas, rescate subacuático y evacuaciones sin acceso vehicular continental. La corporación depende del H. Ayuntamiento de Cozumel, dentro de la Dirección de Protección Civil, Bomberos y Guardavidas. Con cincuenta elementos entrenados —incluyendo certificación SCBA de nivel 1 avalada por UNICVA con instructores de Estados Unidos—, dispone de una base principal en San Miguel y un punto avanzado en el oriente de la isla para reducir tiempos de respuesta.\n\nDesde 2024 cuenta con su primer camión cisterna de acero inoxidable en la historia del municipio, una unidad de ataque rápido, una pick-up 4×4 para zonas de difícil acceso y equipo de rescate donado por el Miami Beach Fire Department, fruto de un hermanamiento institucional activo. El Patronato de Bomberos de Cozumel y la Fundación Comunitaria Cozumel IAP complementan el financiamiento público con donaciones ciudadanas y empresariales.',
