        descripcion: 'La Dirección General de Protección Civil y Bomberos del Municipio de Tulum responde a uno de los destinos turísticos de mayor crecimiento en México en la última década. Cuando Tulum se constituyó como municipio 11 de Quintana Roo en 2021, la corporación debió escalar capacidades de forma acelerada para cubrir una mancha urbana en expansión, el Corredor Tulum-Cobá con decenas de cenotes y selva maya, la costa caribeña adyacente a la Reserva de la Biósfera de Sian Ka\'an y el entorno del Aeropuerto Internacional Felipe Carrillo Puerto (TQO/MMTL), inaugurado en diciembre de 2023.\n\nLa estructura institucional distingue tres mandos diferenciados —Director General, Director de Protección Civil y Director de Bomberos—, con correos institucionales propios bajo el dominio tulum.gob.mx, modelo poco común para un municipio de su tamaño. En 2025 recibió equipamiento nuevo y capacitación del CENAPRED en preparación ante riesgos costeros. Su perfil de riesgo combina alta densidad de visitantes extranjeros, ecosistemas de humedales y selva, y fenómenos meteorológicos del Caribe.',
