        descripcion: 'El Departamento de Bomberos del Instituto de Protección Civil del Estado de Tabasco (IPCET) es la institución de respuesta a emergencias con mayor cobertura territorial del estado, operando en los 17 municipios a través de cuatro Centros Regionales —Costa (Comalcalco), Sabana (Huimanguillo), Sierra (Teapa) y Frontera Sur (Tenosique)— y tres bases adicionales: Planicie, Norte y Guayabal. El cuartel central se ubica en la Prolongación de la Avenida Adolfo Ruiz Cortines S/N, Colonia La Manga I, Villahermosa, con turno 24×48 horas los 365 días del año. Bajo la Dirección General del Ing. Armando Pulido Pardo, el IPCET dispone de aproximadamente 145 elementos y 31 equipos mayores incluyendo pipas de 20,000 litros y carros-bomba de ataque ligero y pesado dotados en 2022.\n\nTabasco es el estado con mayor índice de inundaciones de México —en 2007 el 62% del territorio quedó bajo agua y el 75% de la población resultó afectada— lo que ha convertido al IPCET en referente nacional en protección civil ante riesgos hídricos. Mantiene Planes de Emergencia específicos para las cuencas del Grijalva y el Usumacinta, activados en 2020 ante la tormenta tropical Cristóbal (150,000 afectados, 10 ríos desbordados) y en múltiples declaratorias de emergencia. Atiende también incendios en las instalaciones PEMEX de Macuspana y Cárdenas, así como incendios forestales en la sierra tabasco-chiapaneca.',
