/* ─── HELPERS ─────────────────────────────────────────────── */

/** Total de estaciones en el directorio */
export const totalEstaciones = estados.reduce((acc, e) => acc + e.estaciones.length, 0);

/** Total de estados con al menos una estación */
export const totalEstados = estados.filter((e) => e.estaciones.length > 0).length;

/** Todas las estaciones en un array plano */
export const todasLasEstaciones: EstacionBomberos[] = estados.flatMap((e) => e.estaciones);

/** Tipos únicos presentes en el directorio */
export const tiposPresentes: TipoEstacion[] = [
  ...new Set(todasLasEstaciones.map((e) => e.tipo)),
] as TipoEstacion[];

/** Estado por slug */
export function estadoPorSlug(slug: string): EstadoDirectorio | undefined {
  return estados.find((e) => e.slug === slug);
}

/** Estaciones por tipo */
export function estacionesPorTipo(tipo: TipoEstacion): EstacionBomberos[] {
  return todasLasEstaciones.filter((e) => e.tipo === tipo);
}

/** Configuración visual de cada tipo */
export const tipoConfig: Record<TipoEstacion, { label: string; color: string; bgColor: string }> = {
  Municipal:    { label: 'Municipal',    color: '#F75000', bgColor: 'rgba(247,80,0,0.1)' },
  Estatal:      { label: 'Estatal',      color: '#F5A623', bgColor: 'rgba(245,166,35,0.1)' },
  Industrial:   { label: 'Industrial',   color: '#4A7599', bgColor: 'rgba(74,117,153,0.15)' },
  Aeropuerto:   { label: 'Aeropuerto',   color: '#34D399', bgColor: 'rgba(52,211,153,0.1)' },
  PEMEX:        { label: 'PEMEX',        color: '#60A5FA', bgColor: 'rgba(96,165,250,0.1)' },
  CFE:          { label: 'CFE',          color: '#A78BFA', bgColor: 'rgba(167,139,250,0.1)' },
  Voluntarios:  { label: 'Voluntarios',  color: '#94A3B8', bgColor: 'rgba(148,163,184,0.1)' },
};

/** Configuración visual de los niveles de confianza/verificación */
export const confianzaConfig: Record<Confianza, { label: string; color: string; bgColor: string }> = {
  alta:  { label: 'Verificado',   color: '#34D399', bgColor: 'rgba(52,211,153,0.1)' },
  media: { label: 'Confirmado',   color: '#F5A623', bgColor: 'rgba(245,166,35,0.1)' },
  baja:  { label: 'Por confirmar',color: '#94A3B8', bgColor: 'rgba(148,163,184,0.12)' },
};

/** Estación por estado-slug + estación-slug (para rutas L3) */
export function estacionPorSlug(estadoSlug: string, estacionSlug: string): { estado: EstadoDirectorio; estacion: EstacionBomberos } | undefined {
  const estado = estados.find((e) => e.slug === estadoSlug);
  if (!estado) return undefined;
  const estacion = estado.estaciones.find((s) => s.slug === estacionSlug);
  if (!estacion) return undefined;
  return { estado, estacion };
}

/** Todas las parejas estado+estación (para getStaticPaths de fichas L3) */
export const todasLasParejas = estados.flatMap((estado) =>
  estado.estaciones.map((estacion) => ({ estado, estacion }))
);
